private long getByteCount() throws SAXException {
    try {
        if (stream.hasLength()) {
            return stream.getLength();
        } else {
            return stream.getPosition();
        }
    } catch (IOException e) {
        throw new SAXException("Unable to get stream length", e);
    }
}
